sys_script_include.script:
var HoCOHSMCoChairUtils = Class.create();

HoCOHSMCoChairUtils.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
    getCoChairNames: function() {
        var cmn_location_sys_id = this.getParameter("sysparm_cmn_location_sys_id");
        var gr = new GlideRecord('cmn_location');

        gr.get('sys_id', cmn_location_sys_id);
        gr.query();
        var result = {
            employer: "",
            employee: "",
            representative: ""
        };

        if (gr.next()) {
            result.employer = gr.getValue('u_hs_cochair_employer');
            result.employee = gr.getValue('u_hs_cochair_employee');
            result.representative = gr.getValue('u_hs_representative');
            return JSON.stringify(result);
        }
        return "(ERROR: Location not found)";
    },

    updateCoChairs: function() {
        var cmn_location_sys_id = this.getParameter("sysparm_cmn_location_sys_id");
        var employee = this.getParameter("sysparm_employee_co_chair");
        var employer = this.getParameter("sysparm_employer_co_chair");
        var representative = this.getParameter("sysparm_hs_representative");
        var gr = new GlideRecord('cmn_location');

        gr.get(cmn_location_sys_id);
        gr.query();
        gr.next();
        gr.setValue('u_hs_cochair_employer', employer);
        gr.setValue('u_hs_cochair_employee', employee);
        gr.setValue('u_hs_representative', representative);
        gr.update();
        return "confirmed";

    },
    type: 'HoCOHSMCoChairUtils'
});
